<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungen</title><style>*{box-sizing:border-box}body{margin:0;font:14px Segoe UI,Arial;background:#f4f6f8;color:#1f2937}.page{max-width:1450px;margin:auto;padding:28px}.card{background:#fff;border-radius:12px;box-shadow:0 2px 8px #0001;padding:22px}.filters{display:flex;gap:8px;flex-wrap:wrap}input,select,button{padding:9px;border:1px solid #cbd5e1;border-radius:6px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{padding:10px 8px;border-bottom:1px solid #e5e7eb;text-align:left}.money{text-align:right}.open{background:#fffaf0}a{color:#0369a1;text-decoration:none}</style></head><body><div class="page"><div style="text-align:right"><a href="{{ route('frontend.switch','classic') }}">← Zur klassischen Ansicht</a></div><h1>Rechnungen</h1><div class="card"><form class="filters" method="get"><input name="q" value="{{ request('q') }}" placeholder="Rechnung, Auftrag, Kunde"><select name="status"><option value="all" @selected($status==='all')>Alle</option><option value="open" @selected($status==='open')>Offen</option><option value="paid" @selected($status==='paid')>Bezahlt</option></select><button>Filtern</button></form>@if($rechnungen->isEmpty())<p>Keine Rechnungen gefunden.</p>@else<table><thead><tr><th>Rechnung</th><th>Datum</th><th>Fällig</th><th>Kunde</th><th>Auftrag</th><th>Betrag</th><th>Bezahlt</th><th>Status</th><th>Mahnstufe</th></tr></thead><tbody>@foreach($rechnungen as $r)<tr @class(['open'=>(int)$r->boolBezahlt===0])><td><a href="{{ route('rechnungen.show',$r->intID) }}"><strong>{{ $r->intRechNr }}</strong></a></td><td>{{ date('d.m.Y',strtotime($r->datRechnungsDatum)) }}</td><td>{{ date('d.m.Y',strtotime($r->datFaelligkeitsDatum)) }}</td><td>{{ $kunden[$r->intKID]->strName ?? $r->strKundenNameAufRechnung }}</td><td><a href="{{ route('kunden.auftraege.show',[$r->intKID,$r->intAufNr]) }}">{{ $r->intAufNr }}</a></td><td class="money">{{ number_format((float)$r->fRechnungsbetrag,2,',','.') }} €</td><td class="money">{{ number_format((float)$r->fBezahlterBetrag,2,',','.') }} €</td><td>{{ $r->boolBezahlt ? 'Bezahlt' : 'Offen' }}@if($r->bolRechnungStrittig) · Strittig @endif</td><td>{{ $r->intMahnstufe ?? '-' }}</td></tr>@endforeach</tbody></table>{{ $rechnungen->links() }}@endif</div></div><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>